node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

// Get product details for the mouse
const mouse = db.prepare(\"SELECT * FROM products WHERE product_id = ?\").get('PROD-FA0948');
console.log('MOUSE PRODUCT:', JSON.stringify(mouse, null, 2));

// Get product details for the speaker (to check compatibility)
const speaker = db.prepare(\"SELECT * FROM products WHERE name LIKE '%Anker%Bluetooth%Speaker%'\").get();
console.log('SPEAKER PRODUCT:', JSON.stringify(speaker, null, 2));

// Get variants for the mouse
const mouseVariants = db.prepare(\"SELECT * FROM rt_variants WHERE product_id = ?\").all('PROD-FA0948');
console.log('MOUSE VARIANTS (rt_variants):', JSON.stringify(mouseVariants, null, 2));

// Check if there are any product variants or options in other tables
const cartItems = db.prepare(\"SELECT * FROM cart_items WHERE product_id = ?\").all('PROD-FA0948');
console.log('CART ITEMS with mouse:', JSON.stringify(cartItems, null, 2));

// Check products table for all columns
const cols = db.prepare(\"PRAGMA table_info(products)\").all();
console.log('PRODUCTS COLUMNS:', JSON.stringify(cols.map(c=>c.name)));
"

